    const y=ys[r];
    for(let j=0;j<cols;j++){
      const q=bustLocal(y,j/cols*2*Math.PI,p,F),k=r*cols+j;
      V[k*3]=q[0];V[k*3+1]=q[1];V[k*3+2]=q[2];TW[k]=bustTw(q[0],y,F);DZ[k]=LAST_DZ;
    }
