  if(ak!==C.armKey){C.armKey=ak;C.jointKey={};[["R",-1],["L",1]].forEach(([n,s])=>{C.meshes["fore"+n]=buildForearm(p,s);C.meshes["delt"+n]=buildDelt(p,s)});C.handKey=["",""]}
