  const alvo=onde(ch,pernas),r=ikArm(Q,S,s,alvo),L_=s>0?"L":"R";
  Object.assign(Q,{["armAbd"+L_]:r.abd,["armFlex"+L_]:r.flex,["armRot"+L_]:r.rot,["elbow"+L_]:r.elbow},extra||{});
}
